#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Apply a bundled update: ONE file to upload instead of a dozen.

WHY THIS EXISTS
Every change to this project has meant uploading five to fifteen files through the
GitHub web UI, one at a time, and a single missed file has repeatedly produced a
green tick on a run that harvested nothing. The failure mode is not "I forgot" so
much as "there is no way to tell": a stale `harvest_cemeteries.py` next to a fresh
`cemeteries.yml` looks exactly like a correct repository.

So: everything that changed goes into one self-extracting file. Upload this,
run the "Apply update" workflow, and it writes every file at once and commits
them together. Either the whole update lands or none of it does.

HOW TO USE IT
  1. Upload this file to the repository root (replacing any previous copy).
  2. Actions -> "Apply update" -> Run workflow.
  3. It writes the files, prints what changed, and commits.

You can also run it locally: `python apply_update.py` in a clone.

WHAT IT WILL NOT DO
GitHub's built-in token is not allowed to modify anything under
`.github/workflows/`. A job that tries gets a 403 on push, and the whole commit
fails -- so workflow files in a bundle are written to `_workflows_to_copy/` and
listed at the end instead. Those still need pasting by hand, but they change far
less often than the harvesters and the map.

VERIFICATION
Each file carries a SHA-256 of its intended contents, checked after writing. A
truncated upload or a mangled copy-paste is caught here rather than three hours
into a harvest.
"""

import base64
import hashlib
import io
import json
import os
import sys
import zlib

# ---------------------------------------------------------------------------
# The payload. Written by the build step; each entry is
#   path -> {"sha256": <hex of the decoded bytes>, "b64": <zlib+base64>}
# ---------------------------------------------------------------------------
BUNDLE_VERSION = '2026-10-19b'
_PAYLOAD = r"""{"SOURCES.md":{"sha256":"211412913baae41f9123d8b87edb921e55e7f908c49ebe93662f3171d08464fa","b64":""},"harvest_remains.py":{"sha256":"a83265959fc30417a0903451c0a5235ac9f400a74aaea0fbd0ce360d5f9b3b81","b64":""},"harvest_cemeteries.py":{"sha256":"257ccd79a9e09eef13dd7bd5c6bdce614743b5792f868b8cfa6458e72cf15f43","b64":""},"prune_tiles.py":{"sha256":"b4bde3b333dc24c35572a04d6997e0483307d611f4510a71496fa62b7ca3acc5","b64":""},"build_overview.py":{"sha256":"69c6c9292e994d1f921f085e5afec581bb34627fc1df79cfcc57da210eaddb28","b64":""},"index.html":{"sha256":"d758995f232a2935c78b719b6e5d122f15cd8fc1641b6e0c75994497e0bc48c6","b64":""}}"""
FILES = json.loads(_PAYLOAD)

WORKFLOW_PREFIX = ".github/workflows/"
PARKED = "_workflows_to_copy"


def _decode(entry):
    raw = zlib.decompress(base64.b64decode(entry["b64"]))
    got = hashlib.sha256(raw).hexdigest()
    if got != entry["sha256"]:
        raise ValueError("checksum mismatch: expected %s, got %s"
                         % (entry["sha256"][:12], got[:12]))
    return raw


def main():
    if not FILES:
        print("This bundle is empty -- nothing to apply.")
        return 0

    print("Bundle %s: %d file(s)\n" % (BUNDLE_VERSION, len(FILES)))
    written, unchanged, parked, failed = [], [], [], []

    for path in sorted(FILES):
        try:
            raw = _decode(FILES[path])
        except Exception as e:
            failed.append((path, str(e)))
            print("  FAILED   %-42s %s" % (path, e))
            continue

        target = path
        if path.startswith(WORKFLOW_PREFIX):
            # See the note at the top: the built-in token cannot push these.
            target = os.path.join(PARKED, os.path.basename(path))
            parked.append(path)

        d = os.path.dirname(target)
        if d:
            os.makedirs(d, exist_ok=True)

        if os.path.exists(target):
            with open(target, "rb") as fh:
                if hashlib.sha256(fh.read()).hexdigest() == FILES[path]["sha256"]:
                    unchanged.append(path)
                    print("  same     %s" % path)
                    continue

        with open(target, "wb") as fh:
            fh.write(raw)
        with open(target, "rb") as fh:
            if hashlib.sha256(fh.read()).hexdigest() != FILES[path]["sha256"]:
                failed.append((path, "verify-after-write failed"))
                print("  FAILED   %-42s did not verify after writing" % path)
                continue
        written.append(path)
        print("  wrote    %-42s %d bytes" % (target, len(raw)))

    print("\n%d written, %d already current, %d failed"
          % (len(written), len(unchanged), len(failed)))

    if parked:
        print("\n  ----------------------------------------------------------")
        print("  %d WORKFLOW FILE(S) COULD NOT BE COMMITTED BY THIS JOB." % len(parked))
        print("  GitHub's built-in token may not modify .github/workflows/.")
        print("  They are written to %s/ -- copy each into place by hand:" % PARKED)
        for p in parked:
            print("     %s  ->  %s" % (os.path.join(PARKED, os.path.basename(p)), p))
        print("  ----------------------------------------------------------")

    # Post-step: rebuild derived files from data ALREADY in the repository, so a
    # map change that needs them works now instead of after the next harvest.
    if not failed and os.path.exists("build_overview.py") \
            and os.path.exists("remains_local_manifest.json"):
        print("\nBuilding facility world-view files from the tiles in the repo:")
        try:
            import importlib
            sys.path.insert(0, os.getcwd())
            importlib.import_module("build_overview").main()
        except Exception as e:
            print("  overview: not built (%s) -- the map falls back to tiles" % e)

    if failed:
        print("\nFAILURES -- nothing downstream should be trusted until these are fixed:")
        for p, why in failed:
            print("   %-42s %s" % (p, why))
        return 1
    return 0




if __name__ == "__main__":
    sys.exit(main())
